// format(str, ...args)：剩余参数是一个数组。替换值在 JS 里经 ToString，数字由调用处用 js::toString 转好
// /{(\d+)}/g：std::regex 不接受不成对的 {，写成 \{ \}，含义相同
static const js::Regex placeholder("\\{(\\d+)\\}", "g");
return js::replace(str, placeholder, [&args](const std::vector<std::string>& match) -> std::string {
  // args[index]：index 是数字串，只有规范的数组下标（"0"，或不以 0 开头）且小于 args.length 时才有值，
  // 否则是 undefined，保留原文 match
  const double index = js::toNumber(match[1]);
  if (js::toString(index) != match[1] || index >= static_cast<double>(args.size())) {
    return match[0];
  }
  return args[static_cast<std::size_t>(index)];
});

