// {type: "text" | "think" | "code", content, lang?, completed?}，键按 JS 对象字面量的顺序
std::vector<js::Json> result;
int lastIndex = 0;
int regexLastIndex = 0;  // regex.lastIndex: the literal makes a fresh RegExp per call
while (const auto match = js::exec(regex, markdown, regexLastIndex)) {
  const auto& m = match->groups;
  if (match->index > lastIndex) {
    const std::string text = js::slice(markdown, lastIndex, match->index);
    if (!js::trim(text).empty()) {
      result.push_back(js::Json{{"type", "text"}, {"content", text}});
    }
  }
  if (js::startsWith(m[0], "```")) {
    // match[2] && match[2].trim(): an unmatched group is ""
    if (!js::trim(m[2]).empty()) {
      result.push_back(js::Json{{"type", "code"}, {"lang", m[1]}, {"content", m[2]}, {"completed", true}});  // match[1] || ""
    }
  } else if (js::startsWith(m[0], "<think>")) {
    if (!js::trim(m[3]).empty()) {
      result.push_back(js::Json{{"type", "think"}, {"content", m[3]}, {"completed", true}});
    }
  }
  lastIndex = regexLastIndex;
}
// Handle any remaining text after the last match
if (lastIndex < js::length(markdown)) {
  const std::string text = js::slice(markdown, lastIndex);
  // Check for unfinished <think> block
  const int thinkStart = js::indexOf(text, "<think>");
  const int codeStart = js::indexOf(text, "```");
  if (thinkStart != -1 && (codeStart == -1 || thinkStart < codeStart)) {
    const std::string beforeThink = js::slice(text, 0, thinkStart);
    if (!js::trim(beforeThink).empty()) {
      result.push_back(js::Json{{"type", "text"}, {"content", beforeThink}});
    }
    const std::string thinkContent = js::slice(text, thinkStart + 7);
    if (!js::trim(thinkContent).empty()) {
      result.push_back(js::Json{{"type", "think"}, {"content", thinkContent}, {"completed", false}});
    }
  } else if (codeStart != -1) {
    const std::string beforeCode = js::slice(text, 0, codeStart);
    if (!js::trim(beforeCode).empty()) {
      result.push_back(js::Json{{"type", "text"}, {"content", beforeCode}});
    }
    // Try to detect language after ```
    static const js::Regex langPattern("^(\\w+)?\\n");
    const auto codeLangMatch = js::match(js::slice(text, codeStart + 3), langPattern);
    std::string lang;
    int codeContentStart = codeStart + 3;
    if (codeLangMatch) {
      lang = (*codeLangMatch)[1];  // codeLangMatch[1] || ""；没参与匹配的组是 ""
      codeContentStart += js::length((*codeLangMatch)[0]);
    } else if (js::charAt(text, codeStart + 3) == "\n") {
      // ii: 走不到：``` 后面紧跟 \n 时上面的正则已经匹配
      codeContentStart += 1;
    }
    const std::string codeContent = js::slice(text, codeContentStart);
    if (!js::trim(codeContent).empty()) {
      result.push_back(js::Json{{"type", "code"}, {"lang", lang}, {"content", codeContent}, {"completed", false}});
    }
  } else if (!js::trim(text).empty()) {
    result.push_back(js::Json{{"type", "text"}, {"content", text}});
  }
}
// console.log(JSON.stringify(result, null, 2));
return result;

